// Confere se a entrega pode ser acionada e monta as linhas para Entregas e Pedidos.
const entrada = $('Entrada').first().json;

function soDigitos(v) { return String(v ?? '').replace(/\D/g, ''); }
function normalizar(s) {
  return String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}
function minutos(hhmm) {
  const m = /(\d{1,2}):(\d{2})/.exec(String(hhmm ?? ''));
  return m ? Number(m[1]) * 60 + Number(m[2]) : NaN;
}

// Horário de funcionamento (aba Configuração)
const config = {};
for (const item of $('Ler configuracao').all()) config[item.json.parametro] = item.json.valor;
const abre = minutos(config.horario_abertura);
const fecha = minutos(config.horario_fechamento);
const agora = $now.setZone('America/Sao_Paulo');
const agoraMin = agora.hour * 60 + agora.minute;
const dentroDoHorario = Number.isFinite(abre) && Number.isFinite(fecha) && agoraMin >= abre && agoraMin < fecha;

// Pedido (aceita "PED-0008", "ped-8" ou só "8")
const num = /(\d+)/.exec(String(entrada.id_pedido ?? ''));
const idPedido = num ? 'PED-' + String(Number(num[1])).padStart(4, '0') : '';
const pedido = $('Ler pedidos').all().map(i => i.json).find(p => String(p.id_pedido ?? '').trim().toUpperCase() === idPedido);

let erro = null;
if (!idPedido) erro = 'Número do pedido não informado. Use o número que registrar_pedido retornou, por exemplo PED-0008.';
else if (!pedido) erro = `O pedido ${idPedido} não foi encontrado. Use o número que registrar_pedido retornou.`;
else if (soDigitos(pedido.telefone_cliente) !== soDigitos(entrada.telefone)) erro = `O pedido ${idPedido} não pertence a este cliente.`;
else if (normalizar(pedido.status) === 'cancelado') erro = `O pedido ${idPedido} está cancelado. Transfira para um atendente se o cliente quiser refazer.`;

// Entrega já existe?
const entregas = $('Ler entregas').all().map(i => i.json).filter(e => e && e.id_entrega);
const existente = entregas.find(e => String(e.id_pedido ?? '').trim().toUpperCase() === idPedido);
if (!erro && existente) {
  return [{ json: { acionar: false, mensagem:
    `A entrega do pedido ${idPedido} já foi acionada antes (${existente.id_entrega}, situação: ${existente.status}). Não chame acionar_entrega de novo para este pedido.` } }];
}
if (erro) return [{ json: { acionar: false, mensagem: 'ENTREGA NÃO ACIONADA. ' + erro } }];

// Próximo número de entrega
let maior = 0;
for (const e of entregas) {
  const m = /^ENT-(\d+)$/.exec(String(e.id_entrega).trim());
  if (m) maior = Math.max(maior, Number(m[1]));
}
const idEntrega = 'ENT-' + String(maior + 1).padStart(4, '0');

// Motoboy do turno (aba Atendentes), só dentro do horário
let motoboy = '';
if (dentroDoHorario) {
  const motoboys = $('Ler atendentes').all().map(i => i.json)
    .filter(a => normalizar(a.funcao) === 'motoboy' && normalizar(a.ativo) === 'sim');
  const doTurno = motoboys.find(a => {
    const [ini, fim] = String(a.horario ?? '').split(/a|às|-|até/i).map(minutos);
    return Number.isFinite(ini) && Number.isFinite(fim) && agoraMin >= ini && agoraMin < fim;
  });
  motoboy = (doTurno || motoboys[0] || {}).nome || '';
}

const observacao = dentroDoHorario
  ? 'Acionada pelo atendente virtual. Aguardando o motoboy sair.'
  : `Pedido feito fora do horário. Sai a partir das ${config.horario_abertura}.`;

const mensagem = dentroDoHorario
  ? `ENTREGA ACIONADA: ${idEntrega} para o pedido ${idPedido}${motoboy ? ` (motoboy: ${motoboy})` : ''}. ` +
    `Avise o cliente que o pedido vai sair para entrega e chega em 30 a 40 minutos. Se o pagamento for Pix, a equipe vai conferir o pagamento.`
  : `ENTREGA AGENDADA: ${idEntrega} para o pedido ${idPedido}. A farmácia está fora do horário de entrega agora. ` +
    `Avise o cliente que o pedido está registrado e sai para entrega a partir das ${config.horario_abertura}.`;

return [{
  json: {
    acionar: true,
    mensagem,
    entrega: {
      id_entrega: idEntrega,
      id_pedido: idPedido,
      motoboy,
      endereco: pedido.endereco_entrega,
      bairro: pedido.bairro,
      status: 'Pendente',
      saiu_em: '',
      entregue_em: '',
      observacoes: observacao,
    },
    pedido: { id_pedido: idPedido, status: 'Aguardando entrega' },
  }
}];
